import {accountReturnTo} from './account-journey.mjs';
const icon=name=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const logo='<a class="brand" href="/" aria-label="Affimaro home"><span class="brand-mark"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M8 22V13a8 8 0 0 1 16 0v9M8 17h16M16 17v8"/></svg></span><span>affimaro<span class="brand-period">.</span></span></a>';
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,href,kind='dark')=>`<a class="btn btn-${kind}" href="${href}">${label}${icon('arrow')}</a>`;
const intro=(eyebrow,title,text)=>`<div class="m-section-heading"><span class="eyebrow">${eyebrow}</span><h2>${title}</h2><p>${text}</p></div>`;
const featureCards=items=>`<div class="m-card-grid">${items.map(([symbol,title,text,href])=>`<article class="m-feature-card"><span class="m-feature-icon">${icon(symbol)}</span><h3>${title}</h3><p>${text}</p>${href?`<a class="text-link" href="${href}">Explore ${title.toLowerCase()}${icon('arrow')}</a>`:''}</article>`).join('')}</div>`;
const steps=items=>`<ol class="m-process">${items.map(([title,text],i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><h3>${title}</h3><p>${text}</p></li>`).join('')}</ol>`;
const faqs=items=>`<div class="m-faq-list">${items.map(([question,answer])=>`<details><summary>${question}${icon('plus')}</summary><p>${answer}</p></details>`).join('')}</div>`;
const cta=(title='Better partnerships start with a clear next step.')=>`<section class="m-closing container"><span class="eyebrow">FOUR DEDICATED PORTALS</span><h2>${title}</h2><p>Choose the account and tools that match your work.</p><div class="m-actions">${[['Brand','brand'],['Creator','creator'],['Affiliate','affiliate'],['Agency','agency']].map(([name,id])=>button('Start as a '+name.toLowerCase(),'/auth/'+id+'/signup',id==='brand'?'dark':'white')).join('')}</div></section>`;

