export function marketingHeader(active=''){
  return `<header class="site-header" id="site-header"><div class="m-header-inner">${logo}<button class="mobile-nav-toggle" type="button" aria-label="Open navigation" aria-controls="main-nav" aria-expanded="false">${icon('menu')}</button><nav class="main-nav" id="main-nav" aria-label="Main navigation">${menus.map(([label,href,key,items])=>`<div class="m-nav-item"><div class="m-nav-label"><a href="${href}"${active===key?' aria-current="page"':''}>${label}</a><button class="m-nav-expand" type="button" aria-label="Show ${label.toLowerCase()} menu" aria-controls="menu-${key}" aria-expanded="false">${icon('chevron')}</button></div><div class="m-nav-panel" id="menu-${key}" aria-label="${label} services"><div class="m-menu-intro"><span class="eyebrow">${label.toUpperCase()}</span><strong>A clearer way<br>to work together.</strong><a class="text-link" href="${href}">Explore ${label.toLowerCase()}${icon('arrow')}</a></div><div class="m-menu-links">${items.map(([symbol,title,text,url])=>`<a href="${url}"><span>${icon(symbol)}</span><div><strong>${title}</strong><small>${text}</small></div>${icon('arrow')}</a>`).join('')}</div></div></div>`).join('')}<a class="m-pricing-link" href="/pricing"${active==='pricing'?' aria-current="page"':''}>Pricing</a></nav><div class="m-header-actions"><a class="m-login" href="/login">Log in</a>${button('Get started','/get-started','dark')}</div></div></header>`;
}
