for(const [key,f] of Object.entries(features))marketingPages['/features/'+key]={title:f.title+' | Affimaro',description:f.description,active:'platform',body:`<section class="m-page-hero container"><span class="eyebrow">${f.title.toUpperCase()}</span><h1>${f.lead}</h1><p>${f.description}</p><div class="m-actions">${button('Explore the brand portal','/demo/brands')}${button('Explore the affiliate portal','/demo/affiliates','white')}</div></section><section class="m-section container">${featureCards(f.cards)}</section><section class="m-section m-tinted"><div class="container">${intro('HOW IT WORKS','A practical workflow,<br>from one step to the next.','Follow the underlying order, approval and account permissions rather than relying on a single headline balance.')}${steps(f.steps)}</div></section><section class="m-section container"><div class="m-callout"><h2>Connected to the rest of your program.</h2><p>Use the supported store connection, keep your partner decisions current and review your reports alongside payment activity.</p><div class="m-actions">${button('Store integrations','/integrations','outline')}${button('Read the guides','/resources','white')}</div></div></section>${cta()}`};

const integrationData={
  woocommerce:{name:'WooCommerce',symbol:'W',text:'A WordPress plugin for signed referral, order and refund delivery.',steps:[['Create the connection','Enter your exact WooCommerce HTTPS home URL in your brand’s Store settings.'],['Install and configure','Upload the plugin ZIP. Save the displayed Affimaro URL, connection ID and one-time signing key in WooCommerce → Affimaro.'],['Test the journey','Run the connection test, then verify a real staging referral, paid order and partial/full refund.']],download:'/downloads/affimaro-woocommerce.zip',downloadLabel:'Download plugin',guide:'/downloads/woocommerce-setup.md',note:'The plugin must be installed on your store. Creating or downloading credentials does not by itself connect a website.'},
  shopify:{name:'Shopify',symbol:'S',text:'Connect a merchant-owned app and import orders through dashboard sync.',steps:[['Prepare your Shopify app','Use a merchant-owned app in the same Shopify organization as the store and grant read_orders.'],['Verify the connection','Enter the app credentials in the Shopify section of your brand’s Store settings.'],['Sync before reviewing','Complete dashboard sync to import eligible conversions and current refunds. Run a recent complete sync before financial approvals.']],download:null,downloadLabel:null,guide:'/downloads/shopify-setup.md',note:'This connection is a merchant-owned app workflow, rather than an App Store installation. Attribution is attached to imported native conversions, with up to a 30-day window.'},
  custom:{name:'Custom websites',symbol:'↗',text:'Connect a website with its own backend using the signed server client.',steps:[['Create a custom connection','Choose Custom website in Store settings and save the exact website home URL.'],['Install on your backend','Give the server client and guide to your developer. Keep its signing key in server-side secret settings.'],['Deliver and verify','Implement referral sessions and reliable order/refund delivery, then verify a staging checkout.']],download:'/downloads/affimaro-custom.mjs',downloadLabel:'Download server client',guide:'/downloads/custom-website-setup.md',note:'The Node.js 22.13+ client signs deliveries; your developer supplies trusted sessions, payment verification and a durable delivery queue. The guide also documents the protocol for other backends.'},
};
marketingPages['/integrations']={title:'Website & store integrations | Affimaro',description:'Connect WooCommerce, Shopify or a custom website to Affimaro referral and commission tracking.',active:'platform',body:`<section class="m-page-hero container"><span class="eyebrow">WEBSITE CONNECTIONS · FOR BRANDS</span><h1>Your website.<br><em>Sales connected to referrals.</em></h1><p>Brands connect the website where their customers buy products or services. This lets Affimaro record referred orders, refunds and commission. Affiliates use their approved referral links and do not need to connect a store.</p><p>For a hosting company, software service or other custom website, choose the custom backend connection below. Customers continue to buy directly from the brand.</p></section><section class="m-section container">${featureCards(Object.entries(integrationData).map(([key,c])=>['plug',c.name,c.text,'/integrations/'+key]))}</section><section class="m-section m-tinted"><div class="container">${intro('VERIFY THE WORKFLOW','A connection test is a start.<br>An order test completes the picture.','Use a staging store to verify consent, attribution, paid orders, refunds and account isolation before sharing live links widely.')}${steps([['Choose one connection','The current release supports one website per brand workspace.'],['Follow its setup guide','Each connection has its own requirements and verification steps.'],['Check both sides','Compare the brand order record, affiliate earnings and reported commission.']])}</div></section>${cta()}`};
for(const [key,c] of Object.entries(integrationData))marketingPages['/integrations/'+key]={title:c.name+' integration | Affimaro',description:c.text,active:'platform',body:`<section class="m-page-hero container"><span class="eyebrow">STORE INTEGRATION</span><h1>${c.name}.<br><em>Connected to your program.</em></h1><p>${c.text}</p><div class="m-actions">${c.download?button(c.downloadLabel,c.download):''}${button('Download setup guide',c.guide,'outline')}</div></section><section class="m-section container">${steps(c.steps)}<div class="m-callout"><h2>Before you go live</h2><p>${c.note}</p><p>Estimated commission still needs brand approval. This connection never automatically sends an affiliate payment.</p>${button('Open brand setup','/workspace?tab=store','outline')}</div></section>${cta()}`};

const guides={
  'brand-start':{title:'Launch your first partner program',eyebrow:'FOR BRANDS',text:'A practical starting point for a brand account, from business details to your first verified referred order.',steps:[['Create and verify your brand account','Create your brand login and verify your email. Complete the business, website, audience and program profile, then submit it to the Affimaro owner. Your brand portal opens only after approval.'],['Review your program rules','Check the commission rate and attribution window in Program settings. Save the rules you want new referrals to use.'],['Connect your website','Choose WooCommerce, Shopify or Custom website in Store settings. Follow its guide and verify the connection.'],['Invite your first affiliate','Share the program application link. The affiliate creates their own account and explicitly applies. Review the application in your brand dashboard.'],['Test an order and refund','Use an approved link on a staging website. Compare order, commission and refund records in both portals before wider use.']],action:['Open brand sign in','/auth/brand/login']},
  'affiliate-start':{title:'Your first brand invitation',eyebrow:'FOR AFFILIATES',text:'Start with your own affiliate account and a brand’s program invitation. A brand subscription is not required.',steps:[['Create and verify your affiliate account','Create your affiliate login and verify your email. Complete your channels, audience, experience and promotion strategy, then submit your profile for owner review. Your affiliate portal opens only after approval.'],['Open a brand’s invitation','Use the application link the brand shares. Check the business website, rate and attribution window.'],['Review before applying','Saving a profile does not send an application. Choose Apply to this program when you are ready to share your profile with that business.'],['Wait for the brand’s decision','Your application page and affiliate portal show the current status. An approved referral link appears when the program and verified store are active.'],['Follow your own results','Use your approved link and inspect your referred orders and commission. Available earnings depend on eligibility, refunds and brand approval.']],action:['Open affiliate sign in','/auth/affiliate/login']},
  payments:{title:'Understand commission and payment records',eyebrow:'FOR BOTH SIDES',text:'Keep three ideas distinct: commission estimated from orders, commission approved by the brand, and an actual payment.',steps:[['Read the order state','Eligible processing/completed orders may accrue commission. Pending payment has no accrued commission; refunds can reduce or reverse it.'],['Review approval and availability','The brand approves earned commission. An available balance accounts for reservations, payments and later refund adjustments.'],['Create a supported request','The affiliate requests available approved commission to a saved bank destination or an eligible Stripe receiving account.'],['Pay directly and record accurately','The brand makes a bank/Wise transfer outside Affimaro and records its completion, or explicitly confirms a supported USD Stripe transfer.'],['Check the final record','A request is not proof of settlement. Bank records are entered by the brand. Verified Stripe transfers confirm connected-account credit; subsequent bank payout is separate.']],action:['Read payment setup','/downloads/payments-setup.md']},
};
for(const [key,g] of Object.entries(guides))marketingPages['/guides/'+key]={title:g.title+' | Affimaro',description:g.text,active:'resources',body:`<article class="container m-guide"><header><span class="eyebrow">${g.eyebrow}</span><h1>${g.title}</h1><p>${g.text}</p></header><ol>${g.steps.map(([title,text],i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><div><h2>${title}</h2><p>${text}</p></div></li>`).join('')}</ol><div class="m-actions">${button(g.action[0],g.action[1])}${button('All resources','/resources','outline')}</div></article>`};

marketingPages['/resources']={title:'Guides & resources | Affimaro',description:'Practical guides for brand setup, affiliate invitations, store connections and commission workflows.',active:'resources',body:`<section class="m-page-hero container"><span class="eyebrow">RESOURCE CENTER</span><h1>Less guessing.<br><em>A clearer next step.</em></h1><p>Understand the workflow, choose the right connection and get your own account ready to use.</p></section><section class="m-section container">${featureCards([['store','Start a brand program','Business setup, program rules, store verification and your first approved affiliate.','/guides/brand-start'],['users','Start as an affiliate','Your account, a program invitation, approval and your first referral link.','/guides/affiliate-start'],['wallet','Understand commission','What estimated, approved, reserved and recorded payment amounts mean.','/guides/payments']])}</section><section class="m-section m-tinted"><div class="container">${intro('PUT YOUR SETUP IN CONTEXT','The right guide<br>for your connection.','Read the integration overview first, then download the relevant setup file for your store or developer.')}<div class="m-downloads">${Object.entries(integrationData).map(([key,c])=>`<a href="/integrations/${key}"><strong>${c.name}</strong><span>Requirements, setup and downloads${icon('arrow')}</span></a>`).join('')}<a href="/downloads/reports-guide.md"><strong>Reports and CSV exports</strong><span>Report definitions and exact monetary values${icon('arrow')}</span></a><a href="/install"><strong>Install the web app</strong><span>Android, iPhone and desktop instructions${icon('arrow')}</span></a></div></div></section>${cta()}`};
marketingPages['/help']={title:'Help center | Affimaro',description:'Find answers about separate accounts, program invitations, tracking, commissions and direct payment workflows.',active:'resources',body:`<section class="m-page-hero container"><span class="eyebrow">HELP CENTER</span><h1>A little clarity<br><em>goes a long way.</em></h1><p>Start with these common questions, then follow the relevant guide or connection setup.</p></section><section class="m-section container m-help">${faqs([['Does verifying my email approve my account?','No. Both brands and affiliates complete a detailed application and submit it to the Affimaro owner. Only owner approval opens the relevant portal. You can see requests for more information and decisions on your Application status page.'],['Which account should I create?','Create a brand account to manage your business’s program. Create an affiliate account to participate in brand programs. They have separate onboarding, dashboards and permissions, with no in-dashboard role switch.'],['Can the same account do both?','An account has one primary role. An existing business workspace remains a brand account, while an affiliate profile belongs to an affiliate account. Use a separate account and email when you need the other role.'],['How does an affiliate find a program?','The brand shares its program application link. The current release uses invitation links; a public brand marketplace is not included.'],['Why is an approved referral link missing?','The application must remain approved, the program must be active, and its store connection must be active and verified. The brand controls those settings.'],['Why has an order not appeared?','Confirm the store’s own setup, referral eligibility and delivery status. Shopify needs a dashboard sync. Custom websites need their developer’s server session and event-delivery implementation.'],['Why is commission different after a refund?','Commission uses eligible net merchandise. Partial refunds reduce that amount; full refunds or cancellations reverse commission. An unresolved allocation holds commission for review.'],['Does a payment request mean money was sent?','No. A request reserves approved commission. The brand reviews it and makes a payment through a supported method. Follow the resulting payment record for its current status.'],['Who should I contact about an application or payment?','Contact the brand that runs the program. Its website is linked from the invitation page. Affimaro does not decide which applicants a brand accepts or hold the brand’s affiliate funds.'],['Can I use Affimaro on my phone?','Yes. Install the web app from a supported browser and sign in with your existing account. Your account and financial records need a live connection.'],['Are all advertised packages available?','Starter is $19, Growth $49 and Business $99 USD per month. All three packages can be selected for owner review, with defined partner and agency-directory capacity. Creator and affiliate accounts are free. Choosing a package does not create a subscription or charge a card.']])}<div class="m-actions">${button('Explore all guides','/resources')}${button('Integration setup','/integrations','outline')}</div></section>`};
marketingPages['/about']={title:'About Affimaro',description:'Affimaro is an independent affiliate-management platform, built around clearer programs and dedicated partner portals.',active:'resources',body:`<section class="m-page-hero container"><span class="eyebrow">ABOUT AFFIMARO</span><h1>Good partnerships<br><em>deserve a clear home.</em></h1><p>Affimaro brings program management and affiliate participation into dedicated spaces, connected by a shared record of referrals, orders and commission.</p></section><section class="m-section container m-detail-band"><div><span class="eyebrow">WHY WE ARE BUILDING IT</span><h2>Make the work<br>easier to understand.</h2><p>A brand needs to know who it works with, which orders were referred and what commission it has approved. An affiliate needs to know where their link is, what has been recorded and what is available to request.</p><p>Affimaro is built around those practical questions. It gives each side its own account and tools while keeping the underlying partnership visible.</p></div><div class="m-callout"><h3>What guides the product</h3><ul><li>Separate roles and account permissions</li><li>Explainable commission and refund records</li><li>Store connections with explicit verification</li><li>Payment review before money movement</li><li>Clear descriptions of what is available now</li></ul></div></section><section class="m-section m-tinted"><div class="container">${intro('THE CURRENT CHAPTER','An independent product.<br>A focused pilot.','The current release supports one website and one program per brand workspace, alongside dedicated creator, affiliate and agency portals. Real store setup and payment-provider availability depend on each business’s own configuration.')}<div class="m-actions">${button('Explore the platform','/platform')}${button('View current packages','/pricing','white')}</div></div></section>${cta()}`};
marketingPages['/data-and-privacy']={title:'Data & privacy overview | Affimaro',description:'Understand what Affimaro records, which side can see it, and how account and payment information is scoped.',active:'resources',body:`<article class="container m-guide"><header><span class="eyebrow">DATA & PRIVACY OVERVIEW</span><h1>Your records.<br>A defined purpose.</h1><p>A practical overview of the current product’s data flows and access boundaries.</p></header><section><h2>Application review</h2><p>Brand, affiliate, creator and agency applicants submit contact details, public website/channel URLs, business or audience information and a promotion strategy for the Affimaro owner to review. This application is private to the applicant and authorized owner. It is not a public directory profile. Review decisions and messages appear on the applicant’s status page. No identity documents or bank details are requested in this application. Creator content and agency client-directory records are not public. The account owner manages them; authorized Affimaro platform administration can inspect operational records for service oversight. A directory entry never grants another brand’s account permissions.</p><h2>Account and profile information</h2><p>Affimaro uses your verified identity and saved profile to identify your account. Affiliate profile details are shared with a brand when you choose to apply to that brand’s program. Passwords are not part of the profile shared with a business.</p><h2>Program, referral and order records</h2><p>Brands manage their own programs and connected store records. Affiliates see their own applications, eligible referral links and referred order/commission records. Account permissions are checked on the server.</p><h2>Bank and provider settings</h2><p>Bank destinations and provider credentials are protected server-side and are not included in public pages or report exports. Saved bank/provider secrets use encryption. Relevant payment details are disclosed only within the authorized payment workflow.</p><h2>Payment responsibility</h2><p>Each business funds its own affiliate payments. Bank/Wise payment records are entered by the business. Supported Stripe transfers use the business’s provider connection and explicit review. Affimaro does not hold affiliate funds or store customer card numbers.</p><h2>Device-local examples</h2><p>The separate demo dashboards use synthetic sample data stored in that browser. Demo edits do not create a real account, order or payment. Installed-app caching is limited to public assets and the reconnect page; private account and financial data require a live connection.</p><h2>Understand the workflow before sharing</h2><p>Use the application and connection guides to review what each action records. Contact a program’s business through its linked website for questions about that business’s applications or payment records.</p></section><div class="m-actions">${button('Read the help center','/help','outline')}</div></article>`};
const accountTypes=[
 {id:'brand',path:'/brands',home:'/workspace',label:'Brands & advertisers',title:'Your brand. Your program.',text:'Run your own program, review partners, connect your website and manage commission.'},
 {id:'creator',path:'/creators',home:'/creator',label:'Creators & influencers',title:'Your content. Relevant partners.',text:'Present your channels, plan content and follow approved partnerships and earnings.'},
 {id:'affiliate',path:'/affiliates',home:'/partner',label:'Affiliate partners',title:'Your reach. A clearer record.',text:'Manage publishing properties, program applications, referral links and commission.'},
 {id:'agency',path:'/agencies',home:'/agency',label:'Agencies',title:'Your clients. A clearer workflow.',text:'Keep a private client directory and manage the represented brand program approved for your account.'}
];
const planOptions={starter:['Starter',19],growth:['Growth',49],business:['Business',99]};
function portalChoiceBody(signup,plan,returnTo){
 const selected=Object.hasOwn(planOptions,plan||'')?plan:null;
 let continuation=null;try{if(typeof returnTo==='string'&&returnTo.length<=500&&returnTo.startsWith('/')&&!returnTo.startsWith('//')){const u=new URL(returnTo,'https://app.local');if(u.origin==='https://app.local'&&!u.pathname.startsWith('/auth/'))continuation=u.pathname+u.search+u.hash;}}catch{}
 return `<section class="m-page-hero container m-portal-choice-heading"><span class="eyebrow">${signup&&selected?'BRAND &amp; AGENCY SUBSCRIPTION · STEP 1 OF 3':signup?'CHOOSE YOUR ACCOUNT':'WELCOME BACK'}</span><h1>Four ways to work.<br><em>A portal of your own.</em></h1><p>Brands, creators, affiliate partners and agencies each have their own registration, profile, navigation and dashboard. All accounts require email verification and owner review.</p>${selected?`<div class="m-callout"><h2>${planOptions[selected][0]} · $${planOptions[selected][1]} USD / month</h2><p>For a brand or agency subscription. First sign in or create your account, then complete account review. After approval, continue to secure Stripe checkout. Payment starts only when you confirm in Stripe. Creator and affiliate accounts are free.</p></div>`:''}</section><section class="container m-section"><div class="m-audience-paths">${accountTypes.map(a=>{const paid=a.id==='brand'||a.id==='agency',next=accountReturnTo(a.id,continuation||(selected&&paid?(a.id==='agency'?'/agency/billing':'/billing')+'?plan='+selected:a.home)),href='/auth/'+a.id+'/'+(signup?'signup':'login')+((selected&&paid)||continuation?'?'+(selected&&paid?'plan='+selected+'&':'')+'return_to='+encodeURIComponent(next):'');return `<article><span class="eyebrow">${a.label.toUpperCase()}</span><h3>${a.title}</h3><span class="m-account-price">${paid?'Paid subscription · Brands &amp; agencies':'Free · no subscription'}</span><p>${a.text}</p>${button(signup?(paid?'Create '+a.id+' account':'Create free '+a.id+' account'):a.id[0].toUpperCase()+a.id.slice(1)+' sign in',href)}${signup&&selected&&paid?`<a class="text-link" href="/auth/${a.id}/login?plan=${selected}&amp;return_to=${encodeURIComponent(next)}">Already have an account? Sign in ${icon('arrow')}</a>`:''}<a href="${a.path}">Explore ${a.label.toLowerCase()} ${icon('arrow')}</a></article>`;}).join('')}</div></section><section class="container m-choice-note"><p>Each account has one primary role. Use a separate account and email if you need another role. Your saved records and access remain with their original account.</p></section>`;
}
for(const kind of ['login','get-started'])marketingPages['/'+kind]={title:(kind==='login'?'Log in':'Get started')+' | Affimaro',description:'Choose your own brand, creator, affiliate or agency account.',active:'',body:portalChoiceBody(kind==='get-started')};
marketingPages['/creators']={title:'Creators & influencers | Affimaro',description:'A dedicated creator studio for channels, content planning, reviewed partnerships and commission.',active:'creators',body:`<section class="m-page-hero container"><span class="eyebrow">FOR CREATORS & INFLUENCERS</span><h1>Your content.<br><em>Relevant partners.</em></h1><p>Bring your creative identity and public channels into your own creator account. Plan your next post, apply to invited programs and keep recorded earnings in view.</p><div class="m-actions">${button('Create a creator account','/auth/creator/signup')}${button('Explore the creator demo','/demo/creators','white')}</div><a class="text-link m-hero-login" href="/auth/creator/login">Creator sign in ${icon('arrow')}</a></section><section class="m-section container">${intro('YOUR CREATOR STUDIO','A space for<br>the work you create.','Creator access is free. Your dashboard and navigation stay separate from the affiliate publisher portal.')}${featureCards([['users','Your channel profile','Share your main platform, public portfolio, formats, publishing rhythm and audience for owner review.','/guides/creator-start'],['check','Your content planner','Save ideas and drafts, attach one of your approved partnerships and add the URL when content is published.','/features/creator-studio'],['link','Your partnerships & earnings','Find approved referral links, review recorded orders and request eligible approved commission.','/guides/payments']])}</section><section class="m-section m-tinted"><div class="container">${intro('A REVIEWED START','From your profile<br>to your next partnership.','Affimaro approval opens your creator studio. A brand separately decides whether to accept you into its program.')}${steps([['Create your creator account','Verify your email, complete your creator profile and submit it to the owner.'],['Apply to an invited program','Review the brand’s rules and send your application. Approval is never automatic.'],['Plan, share and follow','Keep your content plan private. Share approved links and follow the orders and commission recorded by the brand.']])}</div></section><section class="m-section container"><div class="m-callout"><h2>Keep the workflow clear.</h2><p>The planner records your ideas, notes and public content URLs. It does not publish to social networks or promise a sponsorship. Brand commission follows eligible referred sales and the brand’s own review.</p><p>Creator accounts are free. A recorded order, an approved commission and a completed payment are separate steps.</p></div></section>${cta()}`};
marketingPages['/agencies']={title:'Agency workspace | Affimaro',description:'A dedicated agency portal for your reviewed profile, client directory and represented partner program.',active:'agencies',body:`<section class="m-page-hero container"><span class="eyebrow">FOR AGENCIES</span><h1>Your clients.<br><em>A clearer workflow.</em></h1><p>Bring your agency identity, business contacts and represented partner program into your own agency account. Keep the client directory separate from each brand’s account permissions.</p><div class="m-actions">${button('Create an agency account','/auth/agency/signup')}${button('Explore the agency demo','/demo/agencies','white')}</div><a class="text-link m-hero-login" href="/auth/agency/login">Agency sign in ${icon('arrow')}</a></section><section class="m-section container">${intro('YOUR OWN AGENCY PORTAL','A directory. A program.<br>A defined responsibility.','Apply with your agency details, services, experience and the business you are authorized to represent.')}${featureCards([['users','Client directory','Save business contacts, engagement status and private notes in your agency workspace.','/features/agency-directory'],['store','Represented program','Manage the approved brand’s partner applications, program rules and connected website.','/guides/agency-start'],['chart','Program reporting','Review scoped order, commission and payment records without opening another account’s data.','/features/reporting']])}</section><section class="m-section m-tinted"><div class="container">${intro('A PRACTICAL FIRST ENGAGEMENT','Your agency.<br>Your represented brand.','All packages include one connected website, one program and one account owner. Package capacity controls approved program partners and client-directory records.')}${steps([['Apply as an agency','Verify your email, complete the agency and represented-brand details and select your package.'],['Complete owner review','Approval opens your own agency portal with its client directory and represented program.'],['Manage within the agreed scope','Review program partners, connected orders and commission. Keep other client contacts in the directory.']])}</div></section><section class="m-section container"><div class="m-callout"><h2>A client contact is not an account permission.</h2><p>Adding a client does not connect its store, grant access to another brand or create a second program. This release manages one represented brand program per agency account. Each business remains responsible for its affiliate payments.</p><a class="text-link" href="/pricing">Choose your agency package ${icon('arrow')}</a></div></section>${cta()}`};
for(const [id,title,items] of [
 ['creator-start','Start with your creator studio',[['Create the right account','Choose Creator on Get started. Verify your email and complete your channels, formats, public portfolio and audience details.'],['Wait for the owner’s review','Your portal opens only after approval. Review messages appear on your application page.'],['Build your partnerships','Open a brand invitation and explicitly apply. The brand separately reviews this program membership.'],['Plan and record your content','Save ideas, drafts and published links in your private planner. Attaching a partnership does not publish content or create commission.']]],
 ['agency-start','Start with your agency workspace',[['Apply as an agency','Choose Agency, provide your business details and confirm your authority to represent the listed brand. Select a package before submitting.'],['Complete owner review','Your agency profile and represented-brand details are reviewed before access opens.'],['Organize your directory','Save client contacts, status and private notes. A directory record does not create an account permission or connect another store.'],['Manage your represented program','Use the one connected website and program approved for this agency account. Review partners, referred orders and commission within that scope.']]]
])marketingPages['/guides/'+id]={title:title+' | Affimaro',description:title,active:'resources',body:`<article class="container m-guide"><header><span class="eyebrow">SETUP GUIDE</span><h1>${title}</h1></header>${items.map(([h,p])=>`<section><h2>${h}</h2><p>${p}</p></section>`).join('')}<div class="m-actions">${button('Create '+(id==='creator-start'?'creator':'agency')+' account','/auth/'+(id==='creator-start'?'creator':'agency')+'/signup')}${button('Account sign in','/auth/'+(id==='creator-start'?'creator':'agency')+'/login','outline')}</div></article>`};
for(const [id,title,body,role] of [
 ['creator-studio','A private workspace for your content.','Plan ideas and drafts, add public URLs and attach one of your approved program partnerships. The creator studio keeps your own notes and content separate from order and commission records.','creator'],
 ['agency-directory','A directory for your client relationships.','Store client contact details, business websites, engagement status and private notes. Records stay with the agency account. A directory entry never creates access to another brand’s program or connects another website.','agency']
])marketingPages['/features/'+id]={title:title+' | Affimaro',description:body,active:role==='creator'?'creators':'agencies',body:`<section class="m-page-hero container"><span class="eyebrow">${role.toUpperCase()} TOOLS</span><h1>${title}</h1><p>${body}</p><div class="m-actions">${button('Create '+role+' account','/auth/'+role+'/signup')}${button('View '+role+' demo','/demo/'+(role==='creator'?'creators':'agencies'),'white')}</div></section>`};
for(const role of ['creator','agency'])marketingPages['/demo/'+(role==='creator'?'creators':'agencies')]={title:role[0].toUpperCase()+role.slice(1)+' demo | Affimaro',description:'An illustrative '+role+' portal preview with synthetic content.',active:role==='creator'?'creators':'agencies',body:`<section class="m-page-hero container"><span class="eyebrow">${role.toUpperCase()} DEMO · ILLUSTRATIVE SAMPLE</span><h1>${role==='creator'?'Your content.<br><em>A studio of your own.</em>':'Your agency.<br><em>A clearer workspace.</em>'}</h1><p>Synthetic sample content. This preview does not read or change any live account, application, order or payment.</p><div class="m-actions">${button('Create '+role+' account','/auth/'+role+'/signup')}${button(role[0].toUpperCase()+role.slice(1)+' sign in','/auth/'+role+'/login','white')}</div></section><section class="m-section container">${role==='creator'?featureCards([['users','Channel profile','Example: video tutorials · weekly publishing · creator portfolio.','/guides/creator-start'],['check','Content planner','Example idea: a product walkthrough. Save drafts and published links in your real creator studio.','/features/creator-studio'],['link','Reviewed partnerships','Real links and earnings appear only after program approval and eligible recorded referrals.','/guides/payments']]):featureCards([['users','Client directory','Example client: Sample Studio · prospect. Your real agency directory stores contacts and private notes.','/features/agency-directory'],['store','Represented program','One connected brand program is managed within the account’s approved scope.','/guides/agency-start'],['chart','Scoped reports','Live reports use only the represented program’s recorded results.','/features/reporting']])}</section>`};
for(const page of Object.values(marketingPages)){
 page.body=page.body.replaceAll('Two dedicated portals.','Four dedicated portals.').replaceAll('Brand and affiliate portals have separate entry points, navigation and account permissions.','Brand, creator, affiliate and agency portals have separate registration, navigation and account permissions.').replaceAll('Brand, affiliate, creator and agency applicants','Brand, affiliate, creator and agency applicants').replaceAll('Growth and Business are planned and unavailable for purchase. Affiliate accounts are free to use.','Approved brands and agencies can purchase all three packages directly. Creator and affiliate accounts are free to use.').replaceAll('Starter describes current capabilities; paid checkout is not open yet.','Every package has defined capacity. Selecting a package does not start a charge.');
}

export function renderMarketingDocument(path,sprite,options={}){
  if(!Object.hasOwn(marketingPages,path))return null;
  const original=marketingPages[path],page=['/login','/get-started'].includes(path)?{...original,body:portalChoiceBody(path==='/get-started',options.plan,options.returnTo)}:original,install=`<a class="corner-install" href="/install" aria-label="Install Affimaro on your device">${icon('download')}<span>Install app</span></a>`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#153b32"><title>${escape(page.title)}</title><meta name="description" content="${escape(page.description)}"><link rel="icon" href="/demo/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/demo/styles.css"><link rel="stylesheet" href="/marketing.css"><script src="/marketing-nav.js" defer></script></head><body class="marketing-page">${sprite}<a class="skip-link" href="#main">Skip to content</a>${marketingHeader(page.active)}<main id="main" tabindex="-1">${page.body}</main>${marketingFooter()}${install}</body></html>`;
}
